local WaxSealPresser = {}
local PRODUCTS = {
    common_wax_seal = { name = "Navadni voščeni pečat", waxCost = 1, time = 2, cost = 25, happiness = 1, description = "Navadni voščeni pečat za pisma." },
    red_cinnabar_seal = { name = "Rdeči cinabaritni pečat", waxCost = 1, ironCost = 1, time = 4, cost = 70, happiness = 1, prestige = 1, description = "Rdeči cinabaritni pečat za listine." },
    silver_impressed_seal = { name = "Srebrno vtisnjeni pečat", waxCost = 2, silverCost = 1, ironCost = 1, time = 7, cost = 200, happiness = 2, prestige = 5, description = "Srebrno vtisnjeni pečat za plemiške dokumente." },
    gold_emblem_seal = { name = "Zlati grbovni pečat", waxCost = 2, goldCost = 1, silverCost = 1, time = 11, cost = 540, happiness = 3, prestige = 14, description = "Zlati grbovni pečat za visoke plemiče." },
    jewel_inlaid_seal = { name = "Draguljarski pečat", waxCost = 3, goldCost = 1, silverCost = 1, jewelCost = 1, time = 15, cost = 1200, happiness = 5, prestige = 26, description = "Pečat z draguljem za visoko plemstvo." },
    royal_imperial_seal = { name = "Kraljevski imperialni pečat", waxCost = 4, goldCost = 2, silverCost = 2, jewelCost = 2, pearlCost = 1, time = 22, cost = 3100, happiness = 10, prestige = 55, description = "Veliki kraljevski imperialni pečat z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    seal_workshop = { name = "Pečatna delavnica", cost = { gold = 180, wood = 80, stone = 80, wax = 6 }, upkeep = 4, qualityBonus = 5 },
    emblem_studio = { name = "Grboslovni atelje", cost = { gold = 720, wood = 220, stone = 220, iron = 6, wax = 10 }, upkeep = 16, qualityBonus = 18 },
    goldsmith_atelier = { name = "Zlatarski atelje", cost = { gold = 2100, wood = 340, stone = 460, silver = 28, gold = 8 }, upkeep = 48, qualityBonus = 30 },
    royal_seal_palace = { name = "Kraljevska pečatna palača", cost = { gold = 8800, wood = 580, stone = 720, gold = 50, jewel = 12 }, upkeep = 180, qualityBonus = 55, prestigeBonus = 50 },
}
WaxSealPresser.waxStock = 16; WaxSealPresser.ironStock = 12; WaxSealPresser.silverStock = 8; WaxSealPresser.goldStock = 6; WaxSealPresser.jewelStock = 4; WaxSealPresser.pearlStock = 4
WaxSealPresser.productStock = {}; WaxSealPresser.buildings = {}; WaxSealPresser.maker = nil; WaxSealPresser.activeMaking = {}; WaxSealPresser.totalProducts = 0; WaxSealPresser.dayTimer = 0
function WaxSealPresser.init() WaxSealPresser.waxStock=16; WaxSealPresser.ironStock=12; WaxSealPresser.silverStock=8; WaxSealPresser.goldStock=6; WaxSealPresser.jewelStock=4; WaxSealPresser.pearlStock=4; WaxSealPresser.productStock={}; WaxSealPresser.buildings={}; WaxSealPresser.maker=nil; WaxSealPresser.activeMaking={}; WaxSealPresser.totalProducts=0; WaxSealPresser.dayTimer=0; print("[WaxSealPresser] Royal Wax Seal Presser System initialized (6 products, 4 buildings)") end
function WaxSealPresser.hireMaker(n,s) s=s or math.random(55,90); local c=420+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; WaxSealPresser.maker={name=n or ("Pečatar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pečatar najet: %s (spretnost: %d)",WaxSealPresser.maker.name,s),"success") end; return true end
function WaxSealPresser.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function WaxSealPresser.build(id) local ok,e=WaxSealPresser.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(WaxSealPresser.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function WaxSealPresser.getQualityBonus() local b=0; for _,bd in ipairs(WaxSealPresser.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function WaxSealPresser.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.waxCost and WaxSealPresser.waxStock<(d.waxCost or 0) then return false,"Premalo voska" end; if d.ironCost and WaxSealPresser.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.silverCost and WaxSealPresser.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and WaxSealPresser.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and WaxSealPresser.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and WaxSealPresser.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #WaxSealPresser.buildings==0 then return false,"Potrebna pečatna delavnica" end; if not WaxSealPresser.maker then return false,"Potreben pečatar" end; return true end
function WaxSealPresser.make(pt,qty) qty=qty or 1; local ok,e=WaxSealPresser.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.waxCost then WaxSealPresser.waxStock=WaxSealPresser.waxStock-d.waxCost*qty end; if d.ironCost then WaxSealPresser.ironStock=WaxSealPresser.ironStock-d.ironCost*qty end; if d.silverCost then WaxSealPresser.silverStock=WaxSealPresser.silverStock-d.silverCost*qty end; if d.goldCost then WaxSealPresser.goldStock=WaxSealPresser.goldStock-d.goldCost*qty end; if d.jewelCost then WaxSealPresser.jewelStock=WaxSealPresser.jewelStock-d.jewelCost*qty end; if d.pearlCost then WaxSealPresser.pearlStock=WaxSealPresser.pearlStock-d.pearlCost*qty end; local t=d.time; if WaxSealPresser.maker then t=math.max(1,t-math.floor(WaxSealPresser.maker.skill/13)) end; table.insert(WaxSealPresser.activeMaking,{id="waxseal_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tiskanje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function WaxSealPresser.completeMaking(m) local q=1.0+(WaxSealPresser.getQualityBonus()/100); if WaxSealPresser.maker then q=q+(WaxSealPresser.maker.skill/150) end; q=math.min(2.4,q); WaxSealPresser.productStock[m.productType]=(WaxSealPresser.productStock[m.productType] or 0)+m.quantity; WaxSealPresser.totalProducts=WaxSealPresser.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if WaxSealPresser.maker then WaxSealPresser.maker.itemsMade=WaxSealPresser.maker.itemsMade+m.quantity; if math.random()<0.25 then WaxSealPresser.maker.skill=math.min(100,WaxSealPresser.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pečat izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"waxseal.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function WaxSealPresser.update(dt) if not _G.state then return end; WaxSealPresser.dayTimer=WaxSealPresser.dayTimer+dt; if WaxSealPresser.dayTimer>=30 then WaxSealPresser.dayTimer=0; for i=#WaxSealPresser.activeMaking,1,-1 do local m=WaxSealPresser.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then WaxSealPresser.completeMaking(m); table.remove(WaxSealPresser.activeMaking,i) end end; local tu=0; for _,bd in ipairs(WaxSealPresser.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if WaxSealPresser.maker then tu=tu+11 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function WaxSealPresser.getStats() return {waxStock=WaxSealPresser.waxStock,ironStock=WaxSealPresser.ironStock,silverStock=WaxSealPresser.silverStock,goldStock=WaxSealPresser.goldStock,jewelStock=WaxSealPresser.jewelStock,pearlStock=WaxSealPresser.pearlStock,productStock=WaxSealPresser.productStock,numBuildings=#WaxSealPresser.buildings,hasMaker=WaxSealPresser.maker~=nil,makerName=WaxSealPresser.maker and WaxSealPresser.maker.name or "—",makerSkill=WaxSealPresser.maker and WaxSealPresser.maker.skill or 0,activeMaking=#WaxSealPresser.activeMaking,totalProducts=WaxSealPresser.totalProducts} end
return WaxSealPresser
